public class Main {
    public static void main(String[] args) {
        // A simplified board holding only the pieces needed to demonstrate rook and pawn rules.
        Board board = new Board();
        board.place(7, 0, 'R'); // white rook, a1
        board.place(6, 4, 'P'); // white pawn, e2
        board.place(0, 0, 'r'); // black rook, a8
        board.place(1, 4, 'p'); // black pawn, e7

        GameSession game = new GameSession(board);

        // White's turn: move the rook horizontally along row 7. Legal, path is clear.
        System.out.println("White rook (7,0) to (7,4): " + game.submitMove('W', 7, 0, 7, 4));

        // Black's turn: an illegal diagonal rook move.
        System.out.println("Black rook (0,0) to (2,2), illegal: " + game.submitMove('B', 0, 0, 2, 2));

        // Still black's turn, since the illegal attempt above did not consume it: a legal pawn double-step.
        System.out.println("Black pawn (1,4) to (3,4): " + game.submitMove('B', 1, 4, 3, 4));

        // White's turn now: an illegal 3-square pawn move.
        System.out.println("White pawn (6,4) to (3,4), illegal: " + game.submitMove('W', 6, 4, 3, 4));

        // Black attempts to move again out of turn.
        System.out.println("Black moves again out of turn: " + game.submitMove('B', 3, 4, 4, 4));

        // White's turn, still: a legal pawn double-step.
        System.out.println("White pawn (6,4) to (4,4): " + game.submitMove('W', 6, 4, 4, 4));

        // Chess clock demo, independent of the moves above.
        ChessClock clock = new ChessClock(10000, 2000); // 10s remaining each, 2s increment
        System.out.println("White uses 4000ms: " + clock.onMoveMade('W', 4000));
        System.out.println("  white remaining: " + clock.remaining('W'));
        System.out.println("Black uses 3000ms: " + clock.onMoveMade('B', 3000));
        System.out.println("  black remaining: " + clock.remaining('B'));
        System.out.println("White uses 9000ms (should time out): " + clock.onMoveMade('W', 9000));
    }
}

// A minimal 8x8 board: '.' for empty, uppercase for white pieces, lowercase for black.
class Board {
    private final char[][] squares = new char[8][8];

    Board() {
        for (char[] row : squares) Arrays.fill(row, '.');
    }

    void place(int row, int col, char piece) {
        squares[row][col] = piece;
    }

    char at(int row, int col) {
        return squares[row][col];
    }

    void move(int fromRow, int fromCol, int toRow, int toCol) {
        squares[toRow][toCol] = squares[fromRow][fromCol];
        squares[fromRow][fromCol] = '.';
    }

    boolean isEmpty(int row, int col) {
        return squares[row][col] == '.';
    }
}

// Validates rook and pawn movement rules against the current board, a
// representative subset standing in for a full legal-move chess engine.
class MoveValidator {
    boolean isLegal(Board board, int fromRow, int fromCol, int toRow, int toCol, boolean isWhite) {
        char piece = board.at(fromRow, fromCol);
        char pieceType = Character.toUpperCase(piece);

        if (pieceType == 'R') {
            return isLegalRookMove(board, fromRow, fromCol, toRow, toCol);
        }
        if (pieceType == 'P') {
            return isLegalPawnMove(board, fromRow, fromCol, toRow, toCol, isWhite);
        }
        return false; // any other piece type is out of scope for this representative subset
    }

    private boolean isLegalRookMove(Board board, int fromRow, int fromCol, int toRow, int toCol) {
        if (fromRow != toRow && fromCol != toCol) {
            return false; // a rook only moves in a straight horizontal or vertical line
        }
        int rowStep = Integer.signum(toRow - fromRow);
        int colStep = Integer.signum(toCol - fromCol);
        int r = fromRow + rowStep;
        int c = fromCol + colStep;
        while (r != toRow || c != toCol) {
            if (!board.isEmpty(r, c)) return false; // the path between start and end must be clear
            r += rowStep;
            c += colStep;
        }
        return true;
    }

    private boolean isLegalPawnMove(Board board, int fromRow, int fromCol, int toRow, int toCol, boolean isWhite) {
        int direction = isWhite ? -1 : 1;             // white moves toward row 0, black toward row 7
        int startingRow = isWhite ? 6 : 1;              // each color's own starting rank in this simplified setup
        if (toCol != fromCol) return false;              // this representative subset does not model diagonal captures
        int rowDelta = toRow - fromRow;
        if (rowDelta == direction) return board.isEmpty(toRow, toCol); // an ordinary single-square forward move
        if (fromRow == startingRow && rowDelta == 2 * direction) {
            return board.isEmpty(fromRow + direction, fromCol) && board.isEmpty(toRow, toCol); // initial two-square move
        }
        return false;
    }
}

// Owns one game's authoritative board and whose turn it currently is,
// rejecting any move that is out of turn or illegal.
class GameSession {
    private final Board board;
    private final MoveValidator validator = new MoveValidator();
    private char turn = 'W'; // white moves first

    GameSession(Board board) {
        this.board = board;
    }

    boolean submitMove(char color, int fromRow, int fromCol, int toRow, int toCol) {
        if (color != turn) {
            return false; // rejected: it is not this player's turn, and the turn does not change
        }
        boolean isWhite = (color == 'W');
        if (!validator.isLegal(board, fromRow, fromCol, toRow, toCol, isWhite)) {
            return false; // rejected: illegal move, and the turn does not change
        }
        board.move(fromRow, fromCol, toRow, toCol);
        turn = (turn == 'W') ? 'B' : 'W'; // only a legal, on-turn move ever passes the turn
        return true;
    }
}

// Tracks each color's remaining time from server-observed elapsed milliseconds,
// applying a small increment after a move that does not time out.
class ChessClock {
    private long remainingWhite;
    private long remainingBlack;
    private final long incrementMillis;

    ChessClock(long startingMillis, long incrementMillis) {
        this.remainingWhite = startingMillis;
        this.remainingBlack = startingMillis;
        this.incrementMillis = incrementMillis;
    }

    // Returns true if the move completed in time; false if this player just timed out.
    boolean onMoveMade(char color, long elapsedMillis) {
        long remaining = (color == 'W') ? remainingWhite : remainingBlack;
        remaining -= elapsedMillis;
        if (remaining <= 0) {
            if (color == 'W') remainingWhite = remaining; else remainingBlack = remaining;
            return false; // timed out; no increment is applied to a player who has already lost
        }
        remaining += incrementMillis;
        if (color == 'W') remainingWhite = remaining; else remainingBlack = remaining;
        return true;
    }

    long remaining(char color) {
        return (color == 'W') ? remainingWhite : remainingBlack;
    }
}

